        heading: '2. 日本の気候区分（6気候）',
        level: 'kiso',
        body: `日本は南北に細長く、季節風（モンスーン）の影響を強く受けるため、地域によって気候が大きく異なる。

■ 6つの気候区分

【1. 日本海側気候】
  特徴：冬に北西の季節風が日本海の水分を運び、多雪・多雨
  代表都市：金沢・新潟・秋田・山形
  雨温図の特徴：冬の降水量が多い（積雪）

【2. 太平洋側気候】
  特徴：夏に南東の季節風で多雨・高温。冬は乾燥し晴天が多い
  代表都市：東京・横浜・高知・仙台（太平洋岸）
  雨温図の特徴：夏の降水量が極端に多い

【3. 瀬戸内海式気候（瀬戸内気候）】
  特徴：中国山地・四国山地に挟まれ、季節風の影響を受けにくい。温暖で少雨
  代表都市：高松・岡山・広島・松山
  雨温図の特徴：年間を通じて降水量が少ない

【4. 内陸性気候（中央高地気候）】
  特徴：海から離れ寒暖差が大きい。夏は高温だが冬は厳しい寒さ
  代表都市：長野・松本・甲府
  雨温図の特徴：夏と冬の気温差が大きい

【5. 北海道の気候（亜寒帯）】
  特徴：梅雨がなく、夏も涼しい。冬は極端に寒冷
  代表都市：札幌・旭川・釧路
  雨温図の特徴：年間降水量が少なく、冬の気温が-10度以下になることも

【6. 南西諸島の気候（亜熱帯）】
  特徴：年間を通じて高温多雨。台風の通り道
  代表都市：那覇・石垣島
  雨温図の特徴：最寒月でも15度以上、年降水量2,000mm超

■ 季節風（モンスーン）のしくみ

  冬（北西の季節風）
  大陸（冷たく乾燥）→ 日本海（水分を吸収）→ 山脈にぶつかり
  日本海側：大雪　　　　　　　　太平洋側：晴れ・乾燥

  夏（南東の季節風）
  太平洋（暖かく湿潤）→ 山脈にぶつかり
  太平洋側：多雨・蒸し暑い　　日本海側：晴れ・フェーン現象

■ フェーン現象
山を越えた空気が高温乾燥になる現象。日本海側の夏や太平洋側の冬に発生。

★ポイント：雨温図問題では「夏と冬のどちらに降水量が多いか」「最寒月気温が何度か」の2点を確認する。
⚠注意：瀬戸内と内陸は両方「少雨」だが、理由が異なる（瀬戸内＝山に囲まれ季節風遮断、内陸＝海から遠い）。`,
