  遣唐使廃止（894年）後、日本独自の文化が発展
  仮名文字（平仮名・片仮名）の発達。女性文学が花開く
  枕草子：清少納言が書いた随筆
  源氏物語：紫式部が書いた世界最古の長編小説とも言われる
  武士の台頭：地方の豪族が武士団を形成。平氏・源氏が力をつける

