  年平均10%前後の急速な経済成長
  東京オリンピック（1964年）：新幹線（東京〜大阪）・首都高速道路が開通
  大阪万博（1970年）：「人類の進歩と調和」テーマ。6400万人来場
  三種の神器：白黒TV・洗濯機・冷蔵庫。後に3Cへ（カラーTV・クーラー・自動車）

