        level: 'kiso',
        body: `三権分立とは、国家権力を「立法・行政・司法」の3つに分け、互いに抑制・均衡させる仕組み。
モンテスキュー「法の精神」で理論化された原理。

■ ASCII 三権分立図

  [国　民]
     |選挙・世論
     v
  [国　会] ─────────────→ [内　閣]
  立法権               内閣不信任決議   行政権
  ・法律の制定     ←─────────────
  ・予算の議決         衆議院解散
     |                                     |
     | 弾劾裁判所                          |
     v                                     v
  [裁 判 所] ←────────── [内　閣]
  司法権             最高裁長官指名・裁判官任命
  違憲審査権
     |
     | 違憲立法審査権
     v
  [国　会]
  （憲法の番人）

■ 国会（立法権）

  衆議院（465議員・任期4年）と参議院（248議員・任期6年）の二院制

【衆参の主な違い】
  +------------------+------------------+------------------+
  | 項目             | 衆議院           | 参議院           |
  +------------------+------------------+------------------+
  | 議員数           | 465名            | 248名            |
  | 任期             | 4年（解散あり）  | 6年（解散なし）  |
  | 被選挙権         | 満25歳以上       | 満30歳以上       |
  | 選挙制度         | 小選挙区+比例    | 選挙区+比例      |
  +------------------+------------------+------------------+

  衆議院の優越：予算の先議権、法律案の再可決（3分の2以上）、内閣信任・不信任決議
  国会の種類：通常国会（毎年1月〜）・臨時国会・特別国会（総選挙後）

■ 内閣（行政権）

  内閣総理大臣（首相）：国会議員の中から国会が指名。天皇が任命
  閣議：内閣総理大臣と国務大臣（閣僚）による会議。全会一致が原則
  議院内閣制：内閣は国会の信任に基づいて成立し、国会に対し連帯責任を負う
  内閣不信任決議：衆議院が可決すると内閣は10日以内に衆議院解散か総辞職

■ 裁判所（司法権）

  最高裁判所（長官1名＋裁判官14名）・高等裁判所・地方裁判所・家庭裁判所・簡易裁判所
  三審制：同一事件について3回まで裁判を受けられる（控訴・上告）
  違憲立法審査権（違憲審査権）：法律・命令・条約が憲法に違反しないか審査
    最高裁判所が「憲法の番人」
  国民審査：最高裁裁判官を国民が罷免できる制度（衆議院選挙と同時実施）

★ポイント：「衆議院の優越」3点セット（予算先議・法律案再可決・内閣信任不信任）は必須。
⚠注意：違憲立法審査権は「全ての裁判所」が持つが、最終決定は最高裁判所（憲法の番人）。`,
