        level: 'oyo',
        body: `■ 財政（国の収入と支出）

【歳入（国の収入）】
  税収：所得税・法人税・消費税が3本柱
  国債（借金）：不足分を賄うための国の借金。残高は1,000兆円超（2024年時点）

【歳出（国の支出）】
  社会保障費（最大）：医療・介護・年金・子育て
  国債費（利払い・元本償還）
  地方交付税交付金・公共事業費・文教科学費

■ 税金の種類

  +------------------+------------------+------------------+
  | 分類             | 直接税           | 間接税           |
  +------------------+------------------+------------------+
  | 意味             | 税を負担する人が | 負担者と納税者が |
  |                  | 直接納める       | 異なる           |
  | 例               | 所得税・法人税   | 消費税・酒税     |
  |                  | 相続税・固定資産税| 関税・たばこ税   |
  +------------------+------------------+------------------+

  累進課税：所得が高いほど税率が高くなる（所得税・相続税）。所得再分配機能

■ 社会保障制度（4本柱）

  1. 社会保険：医療保険・年金保険・雇用保険・労災保険・介護保険
       加入者が保険料を支払い、必要時に給付を受ける
  2. 公的扶助（生活保護）：生活に困窮する人への最低生活保障。全額税負担
  3. 社会福祉：高齢者・障害者・ひとり親家庭等への福祉サービス
  4. 公衆衛生：感染症予防・上下水道整備・廃棄物処理

■ 金融（資金の融通）

【銀行の信用創造】
  銀行は預かったお金の一部を準備金として残し、残りを貸し出す
  貸し出されたお金がまた銀行に預けられ、繰り返すことで元の預金の何倍もの信用が創られる
  例：1,000万円の預金 → 900万円貸出 → 900万円預金 → 810万円貸出…

【日本銀行の3つの役割】
  1. 発券銀行：日本銀行券（お札）を発行する唯一の機関
  2. 政府の銀行：国の資金を管理（国庫金の出納）
  3. 銀行の銀行：市中銀行に資金を貸し出し、預金を受け入れる

【金融政策（日本銀行）】
  景気が過熱→ 市中銀行が持つ国債等を日本銀行が売る（売りオペ）
    → 市中の資金が減少→ 金利上昇→ 景気抑制
  景気が低迷→ 日本銀行が国債等を市中銀行から買う（買いオペ）
    → 市中の資金が増加→ 金利低下→ 景気刺激
  公開市場操作（オープンマーケットオペレーション）：現代の主要な金融政策手段

★ポイント：「日銀＝発券銀行・政府の銀行・銀行の銀行」の3役割は頻出。
⚠注意：財政政策は「政府」が行い、金融政策は「日本銀行（中央銀行）」が行う。主体が異なる。`,
