        level: 'oyo',
        body: `■ 為替レート（円相場）の仕組み

  為替レート：異なる通貨の交換比率
  例：1ドル＝150円 → 円安（ドルに対して円の価値が低い）
      1ドル＝100円 → 円高（ドルに対して円の価値が高い）

■ 円高・円安と輸出入への影響

  +----------+----------------------+----------------------+
  |          | 円高（1ドル=100円） | 円安（1ドル=150円） |
  +----------+----------------------+----------------------+
  | 輸出企業 | 不利（価格が高くなる）| 有利（価格が安くなる）|
  | 輸入企業 | 有利（安く買える）  | 不利（高くつく）    |
  | 旅行者   | 有利（外国が安い）  | 不利（外国が高い）  |
  | 物価     | デフレ圧力          | インフレ圧力        |
  +----------+----------------------+----------------------+

  具体例（円安・1ドル＝150円の場合）：
    1ドルの商品を輸入 → 150円必要（以前より高い）→ 輸入物価上昇 → 生活コスト増
    日本車を1万ドルで輸出 → アメリカでは1万ドルのまま → 円換算で150万円（増収）

■ 貿易摩擦と保護貿易 vs 自由貿易

  保護貿易：関税・輸入制限で国内産業を守る
    長所：国内産業（農業・新興産業）の保護
    短所：非効率な産業が温存・消費者が高値で購入させられる
  自由貿易：関税を下げ、貿易を自由化する
    長所：国際分業の恩恵・物価低下・産業の競争力向上
    短所：競争力の弱い産業が衰退・国際的な不平等が生じることも

■ 国際的な経済連携の枠組み

  +----------+--------------------------------------------+
  | 略称     | 内容                                       |
  +----------+--------------------------------------------+
  | WTO      | 世界貿易機関。自由貿易ルールを決める国際機関|
  | FTA      | 自由貿易協定。特定国間で関税撤廃           |
  | EPA      | 経済連携協定。FTA+投資・知的財産等も含む   |
  | TPP      | 環太平洋パートナーシップ協定               |
  +----------+--------------------------------------------+

■ 日本の貿易相手国Top5（輸出・近年）

  1位：中国　2位：アメリカ　3位：韓国　4位：台湾　5位：香港

■ 経常収支の構成

  経常収支
  +-- 貿易収支：商品の輸出額-輸入額
  +-- サービス収支：運輸・旅行・知財使用料等
  +-- 第一次所得収支：海外への投資収益（配当・利息）
  +-- 第二次所得収支：無償援助・寄付・国際機関への拠出等

  日本は長年、第一次所得収支（海外投資の利益）が黒字の特徴

★ポイント：「円安＝輸出有利・輸入不利」「円高＝輸出不利・輸入有利」をしっかり区別する。
⚠注意：FTA（自由貿易協定）は物品の関税撤廃が中心。EPAはそれに加え投資・人の移動等も含む、より広い概念。`,
