        body: `■ 消費者主権と消費者の権利

  消費者主権：何をどれだけ生産するかは、最終的に消費者の選択が決めるという考え
  ケネディ大統領（アメリカ）が示した「消費者の4つの権利」
    安全を求める権利 / 知らされる権利 / 選ぶ権利 / 意見を反映させる権利

■ 消費者を守る法律・制度（日本）

  消費者基本法（2004年）：消費者の権利の尊重と自立支援を基本理念に
  製造物責任法（PL法・1994年）：
    製品の欠陥で消費者が被害を受けた場合、企業に過失がなくても賠償責任
  消費者契約法：不当な勧誘による契約を取り消せる
  消費者庁（2009年設置）：消費者行政をまとめて担当する国の機関
  クレジットカード・電子マネー・QRコード決済などキャッシュレス化が進行

■ 流通の仕組み

  流通：商品が生産者から消費者に届くまでの流れ
  一般的な流れ：
    生産者 → 卸売業者 → 小売業者 → 消費者

  ASCII 図：
    [生産者] → [卸売業者（問屋）] → [小売業者（スーパー・コンビニ）] → [消費者]

  流通の合理化：
    大規模小売業者（大型スーパー）が生産者から直接仕入れ、卸売を省く
    POSシステム（販売時点情報管理）：バーコードで売れ筋・在庫を管理
    インターネット通販・宅配便の発達で流通が大きく変化

■ 価格の種類

  市場価格：需要と供給で変動する価格
  独占価格・寡占価格：少数の企業が決める価格（下がりにくい）
  公共料金：電気・ガス・水道・鉄道運賃など、国や地方公共団体が決定・認可する価格
    → 生活に不可欠なため、勝手に大きく変動しないよう管理

★ポイント：「PL法＝製品の欠陥は企業に過失がなくても賠償責任」「公共料金＝国・地方が決める」。
⚠注意：流通の合理化は「卸売業者を省いて費用を減らす」こと。中間業者が増えるのではなく減らす方向。`,
