        heading: '2. 時差の計算',
        level: 'oyo',
        body: `■ 時差が生まれる理由

  地球は1日（24時間）で1回転（360度）する
  → 360度 ÷ 24時間 ＝ 経度15度で1時間の時差が生じる

■ 標準時と日本

  各国は基準となる経線（標準時子午線）を決め、その地方時を国全体の標準時とする
  日本の標準時子午線：東経135度（兵庫県明石市を通る）

■ 時差の計算手順（3ステップ）

  (1) 2地点の経度の差を求める
      同じ東経どうし・同じ西経どうし → 引き算
      東経と西経にまたがる → 足し算
  (2) 経度差 ÷ 15 ＝ 時差（時間）
  (3) 東にある地点ほど時刻が進んでいる（早い）
      → 東側の地点の時刻が進み、西側の地点の時刻は遅れる

■ 例題1：日本（東経135度）とロンドン（経度0度）の時差

  経度差 ＝ 135 − 0 ＝ 135度
  時差 ＝ 135 ÷ 15 ＝ 9時間
  日本はロンドンより東にある → 日本の方が9時間進んでいる
  ロンドンが1月1日午前0時のとき、日本は1月1日午前9時

■ 例題2：日本（東経135度）とニューヨーク（西経75度）の時差

  東経と西経にまたがる → 経度差 ＝ 135 ＋ 75 ＝ 210度
  時差 ＝ 210 ÷ 15 ＝ 14時間
  日本の方が東にある → 日本が14時間進んでいる
  日本が1月2日午後3時のとき、ニューヨークは14時間前 → 1月2日午前1時

■ 日付変更線

  ほぼ経度180度に沿って引かれた線
  西から東へ越えるとき：日付を1日戻す
  東から西へ越えるとき：日付を1日進める

★ポイント：「経度15度＝1時間」「東ほど時刻が進む」。この2つだけで時差問題は解ける。
⚠注意：東経と西経にまたがるときは経度を「足す」。同じ側どうしは「引く」。`,
