        body: `■ 戦後日本の産業構造の推移（就業者割合のおおまかな流れ）

  +------------------+----------+----------+----------+
  | 時期             | 第一次   | 第二次   | 第三次   |
  +------------------+----------+----------+----------+
  | 1950年頃         | 約5割    | 約2割    | 約3割    |
  | 高度経済成長期   | 急減     | 拡大     | 拡大     |
  | （1955〜73年）   |          |          |          |
  | 現在             | 約3%     | 約2割台  | 約7割台  |
  +------------------+----------+----------+----------+
  （数値はおおよその傾向を示す）

■ 高度経済成長期（1955〜1973年）の変化

  農村から都市への人口移動（集団就職）。「金の卵」と呼ばれた若年労働力
  重化学工業（鉄鋼・造船・自動車・石油化学）が第二次産業をけん引
  太平洋ベルトに工業地帯・地域が集中し、第二次産業の就業者が急増

■ 1970年代以降：第三次産業化（サービス経済化）

  石油ショック（1973年）後、省エネ型・知識集約型産業へ転換
  金融・情報通信・流通・医療福祉・観光など第三次産業の比重が拡大
  「モノからサービスへ」という消費の変化も背景にある

■ 都道府県別の産業構造の違い（読み取りのコツ）

  第一次産業の割合が高い：北海道・青森・岩手など農林水産業が盛んな県
  第二次産業の割合が高い：愛知（自動車）・三重・静岡など工業県
  第三次産業の割合が極めて高い：東京・大阪・沖縄（観光業）など都市・観光県

■ 農業就業人口の変化

  農業就業人口は減少を続け、高齢化が進む（平均年齢60代後半）
  耕作放棄地の増加、後継者不足が深刻な課題
  対策：スマート農業（ドローン・ICT活用）・新規就農支援・法人化の推進

★ポイント：「高度経済成長＝第二次産業の拡大」「1970年代以降＝第三次産業化（サービス経済化）」の順序を押さえる。
⚠注意：現在の日本は第一次産業の就業者割合が「約3%」程度と非常に低い点を数字で覚える。`,
