        heading: '1. 立憲主義と法の支配',
        level: 'kiso',
        body: `■ 立憲主義とは

  国家権力を憲法によって制限し、国民の権利・自由を保障するという考え方
  「憲法は国家権力を縛るためのもの」という近代的な憲法観の基礎となる原理
  対義語的な考え方：「人の支配」（権力者の意思がそのまま法となる支配のあり方）

■ 法の支配

  国王や権力者の恣意的な支配（人の支配）を排し、
  法（特に憲法）にもとづいて政治権力を行使させるという考え方
  イギリスで発達した考え方で、「法の支配」の下では、権力者も法に従わなければならない

■ 立憲主義と法の支配の関係（ASCII図）

  人の支配（前近代）        法の支配・立憲主義（近代以降）
  権力者の意思＝法      →   憲法・法律が権力者の行動を制限する
  国民は支配される対象      国民の権利・自由を守るために権力を制限

■ 硬性憲法と軟性憲法

  硬性憲法：通常の法律より厳しい改正手続きが必要な憲法（日本国憲法はこちら）
    衆参各議院の総議員の3分の2以上の賛成で国会が発議し、国民投票で過半数の賛成が必要
  軟性憲法：通常の法律と同じ手続きで改正できる憲法
  硬性憲法の意義：時の政権の都合で簡単に改正されないよう、国の基本秩序を安定させる

■ 憲法の最高法規性

  日本国憲法第98条：憲法は国の最高法規であり、これに反する法律・命令・条約等は効力を有しない
  第99条：天皇・国務大臣・国会議員・裁判官その他の公務員は、憲法を尊重し擁護する義務を負う
    → 権力を行使する側にこそ憲法を守る義務が課されている点が立憲主義の核心

★ポイント：「立憲主義＝憲法で国家権力を制限し国民の権利を守る」という考え方の方向性を正確に理解する。
⚠注意：立憲主義は「国民を縛るための憲法」ではなく「権力者を縛るための憲法」という点を混同しないこと。`,
