        body: `■ 日英同盟（1902年）

  背景：満州・朝鮮半島への進出を進めるロシアの南下に対し、
       日本とイギリスがともに警戒感を強めていた
  内容：日本とイギリスが軍事同盟を結び、互いの利害を守り合う関係を構築
  意義：日露戦争において、日本が外交的に孤立せずに戦うための基盤となった

■ 日露戦争と国際的な仲介

  日露戦争（1904〜05年）：満州・朝鮮の支配権をめぐる日本とロシアの戦争
  ポーツマス条約（1905年）：アメリカのセオドア・ルーズベルト大統領が仲介して締結
       日本は韓国における優越権、南満州の権益等を得たが、賠償金は得られなかった
  → 賠償金なしへの国民の不満から日比谷焼打ち事件が発生

■ 韓国併合（1910年）と国際社会の反応

  日本は日露戦争後、韓国への支配を強め、1910年に韓国を併合し植民地化（〜1945年）
  欧米列強は当時、自らも植民地帝国であったため、日本の行動を大きく問題視しなかった
  → この歴史的経緯は、現在の日韓関係における歴史認識問題の背景となっている

■ 第一次世界大戦と日本の国際的地位向上

  日本は日英同盟を理由に連合国側で参戦（1914年）
  中国におけるドイツの権益を接収し、二十一か条の要求（1915年）で中国に権益拡大を要求
  戦後、国際連盟（1920年発足）の常任理事国の一つとなり、国際的地位を高めた

★ポイント：「日英同盟（1902年）＝ロシアの南下に対抗」「日露戦争後の韓国併合（1910年）」を年号とセットで押さえる。
⚠注意：日英同盟はロシアの南下政策に対抗するためのものであり、第一次世界大戦参戦の際にも「参戦の理由」として利用された点に注意。`,
