  歳出が歳入（税収）を上回ると、不足分を国債発行（借金）で賄う
  国債残高の累積は、将来世代の負担（税金による返済）となる可能性がある
  プライマリーバランス（基礎的財政収支）：国債の元利払いを除いた歳出と、
       国債発行に頼らない歳入（税収等）のバランス。黒字化が財政健全化の目安とされる

★ポイント：「財政政策＝政府」「金融政策＝日本銀行」、両方を組み合わせるのが「ポリシーミックス」。
