        heading: '4. 指数・相関と因果の注意点',
        level: 'oyo',
        body: `■ 指数を使った比較

  指数：基準となる年（基準年）の値を100として、それに対する比率で表した数値
  例：ある県の農業産出額が2000年を100として2020年に120という指数の場合、
     2000年に比べて2020年の産出額が20%増加したことを意味する
  指数を使うメリット：単位や規模が異なる複数の資料でも、変化の大きさを比較しやすくなる

■ 相関関係と因果関係

  相関関係：2つの統計データの間に何らかの関連（片方が増えるともう片方も増える等）が見られること
  因果関係：片方の変化が、もう片方の変化の直接の原因になっていること
  重要な注意点：相関関係があるからといって、必ずしも因果関係があるとは限らない
    例：アイスクリームの売上と水難事故の件数には相関関係があるが、
       これは「気温が高い」という共通の原因によるものであり、
       アイスクリームの売上が水難事故を引き起こしているわけではない

■ 統計資料を扱う際の基本姿勢

  数字の裏にある「なぜそうなるのか」という理由まで考える
  一部の極端な数値（外れ値）に引きずられて全体を誤って判断しないよう注意する
  資料の出典・調査方法によって、同じテーマでも数値が異なることがある点に留意する

■ グラフの種類の使い分け（復習と補足）

  棒グラフ：数量の大小比較　　　折れ線グラフ：時間による推移
  円グラフ・帯グラフ：全体に占める割合（構成比）
  散布図：2つの数量の関係（相関関係の有無）を視覚的に確認する際に用いる

★ポイント：「相関関係があっても因果関係があるとは限らない」という考え方は、統計を正しく読み解く上で最も重要な視点の一つ。
⚠注意：指数は「基準年を100とした比率」であり、実数そのものではない点に注意（指数だけでは実際の数量はわからない）。`,
